mapper.select:
SELECT 
FROM sys_agent_task
WHERE task_id = #{taskId}
  AND operator_id = #{operatorId}
LIMIT 1

SELECT 
FROM sys_agent_task
WHERE operator_id = #{operatorId}

    AND status = #{status}

ORDER BY created_time DESC, id DESC
LIMIT #{limit}

SELECT task_id
FROM sys_agent_task
WHERE status = 'RUNNING'
  AND COALESCE(heartbeat_at, claimed_at, updated_time) <= #{staleBefore}
ORDER BY COALESCE(heartbeat_at, claimed_at, updated_time) ASC
LIMIT #{limit}

mapper.update:
UPDATE sys_agent_task
SET heartbeat_at = #{heartbeatAt}, updated_time = CURRENT_TIMESTAMP
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND lease_owner = #{leaseOwner}

UPDATE sys_agent_task
SET status = 'CANCELLED', cancelled_by = #{operatorId}, cancel_reason = #{reason},
    cancelled_at = #{cancelledAt}, completed_at = #{cancelledAt},
    terminal_code = 'CANCELLED_BY_OPERATOR', terminal_reason = #{reason},
    lease_owner = NULL, heartbeat_at = #{cancelledAt}, updated_time = #{cancelledAt}
WHERE task_id = #{taskId}
  AND operator_id = #{operatorId}
  AND status IN ('QUEUED', 'RUNNING', 'WAITING_CONFIRMATION', 'WAITING_INPUT', 'PAUSED')

mapper.select:
SELECT COUNT(1)
FROM sys_agent_task
WHERE status = #{status}
